// Perform Math
var windRad = msg.payload.wind_dir_deg * 0.0174533;
// Signal K range is -pi..pi (negative to port); also avoids 0/360 averaging errors
if (windRad > Math.PI) { windRad -= 2 * Math.PI; }
var battV = msg.payload.battery_mV * 0.001;

// Build the Delta with the 'vessels.self' context
msg.payload = {
    "context": "vessels.self",
    "updates": [
        {
            "source": { "label": "node-red-ws80" },
            "values": [
                {
                    "path": "environment.wind.angleApparent",
                    "value": windRad
                },
                {
                    "path": "electrical.batteries.ws80.voltage",
                    "value": battV
                }
            ]
        }
    ]
};

msg.headers = {
    "Content-Type": "application/json"
};

return msg;

// Expecting msg.payload like:
// { temperature: ..., humidity: ..., pressure: ..., gas_ohms: ... }

let gas;

if (msg.payload && typeof msg.payload === "object") {
    if (typeof msg.payload.gas_ohms === "number") {
        gas = msg.payload.gas_ohms;
    } else if (typeof msg.payload.gasResistance === "number") {
        gas = msg.payload.gasResistance;
    }
}

if (typeof gas !== "number" || !isFinite(gas) || gas <= 0) {
    return null; // ignore bad or missing values
}

// ---- rough, stateless mapping ----
// Tune these min/max to fit your observed range
const minGas = 5000;     // "bad" air (low resistance)
const maxGas = 200000;   // "good" air (high resistance)

// Clamp
let clamped = Math.max(Math.min(gas, maxGas), minGas);

// Map to 0–100 (higher = better)
let score = (clamped - minGas) / (maxGas - minGas) * 100;
score = Math.max(0, Math.min(100, score));
score = Math.round(score);

// Build SignalK delta with both raw and score
msg.headers = { "Content-Type": "application/json" };
msg.method = "POST";
msg.url = "http://localhost:3000/signalk/v1/api/vessels/self/delta";

msg.payload = {
    updates: [{
        source: { label: "bme680.cabin" },
        values: [
            {
                path: "environment.inside.cabin.gasResistance",
                value: gas
            },
            {
                path: "environment.inside.cabin.airQuality",
                value: score
            }
        ]
    }]
};

return msg;

// pypilot plugin publishes 'enabled'/'disabled'; the Signal K schema (and BoatInstrument) expect
// auto | standby | wind | route ...  Re-send a translated value every 3 s from the plugin's own latest value.
const p = msg.payload || {};
const st = p.state || {};
let raw, ts;
if (st.values && st.values['pypilot-sk']) {
    raw = st.values['pypilot-sk'].value; ts = st.values['pypilot-sk'].timestamp;
} else if (st['$source'] === 'pypilot-sk') {
    raw = st.value; ts = st.timestamp;
}
if (typeof raw !== 'string') { return null; }
// if the plugin has gone quiet for 2 minutes, do not paper over it: let the value go stale
if (ts && (Date.now() - Date.parse(ts)) > 120000) { return null; }
const mode = (p.mode && typeof p.mode.value === 'string') ? p.mode.value : 'compass';
let out;
if (raw === 'enabled') {
    out = (mode.indexOf('wind') >= 0) ? 'wind' : ((mode === 'gps' || mode === 'nav') ? 'route' : 'auto');
} else if (raw === 'disabled') {
    out = 'standby';
} else {
    return null;
}
msg.payload = {
    context: 'vessels.self',
    updates: [{ source: { label: 'node-red-ap-state' }, values: [{ path: 'steering.autopilot.state', value: out }] }]
};
return msg;

// No speed-through-water sensor, so Signal K cannot compute environment.wind.speedTrue.
// Use the ground wind speed (derived-data: apparent wind + SOG) as the true wind speed.
const p = msg.payload || {};
const v = p.value;
if (typeof v !== 'number' || !isFinite(v)) { return null; }
// never refresh a stale value: if derived-data stopped (e.g. wind sensor offline) let it go stale
if (p.timestamp && (Date.now() - Date.parse(p.timestamp)) > 30000) { return null; }
msg.payload = {
    context: 'vessels.self',
    updates: [{ source: { label: 'node-red-tws-ground' }, values: [{ path: 'environment.wind.speedTrue', value: v }] }]
};
return msg;
